#!/usr/bin/env node
// DOES A MITIGATED LEVEL STILL REACT — AND DOES ITS POLARITY FLIP?
//
// Two questions in one test, both generated by iapaulo's 19 Aug read (#215) and his much earlier
// breaker observation: "once the liquidity zone is broken it become mor the opposti of what it was
// so it has a dynamic quality to it."
//
//   Q1  Does a MITIGATED order block still produce a reaction when price returns to it, or is it a
//       dead level? #215's `htfContext` defaults to activeOnly and would be discarding real
//       structure if the answer is "yes". iapaulo reads the mitigated weekly OB at 67,612-71,997 as
//       still-live resistance; the model treats it as gone. This settles who is right.
//   Q2  If it does react, does it react in its ORIGINAL polarity or FLIPPED? A bearish OB that price
//       broke ABOVE should, on the breaker reading, act as SUPPORT when price returns down into it.
//
// **NOTHING IN 215 ROWS HAS EVER MEASURED POST-MITIGATION BEHAVIOUR.** #117/#118 measured OB
// recurrence and containment on LIVE blocks only.
//
// CONSTRUCTION
//   Mitigation, per `smc/calc.js`: a BEARISH OB dies when a bar's HIGH clears its top; a BULLISH OB
//   dies when a bar's LOW breaks its bottom. So after mitigation price sits on the far side.
//   Event: the FIRST bar after mitigation on which price RETURNS INTO the block's body.
//     - mitigated bearish OB: price broke up through it, returns DOWN into it
//     - mitigated bullish OB: price broke down through it, returns UP into it
//
//   SIGN CONVENTION, fixed before running: reaction is measured POSITIVE when the level acts with
//   FLIPPED polarity (the breaker reading) and NEGATIVE when it retains its original polarity.
//     - mitigated bearish OB (flipped => support)   => positive means price went UP after the touch
//     - mitigated bullish OB (flipped => resistance) => positive means price went DOWN after
//
//   **THE PLACEBO IS THE WHOLE TEST**, exactly as in #192: price only reaches a level by travelling
//   to it, and any level it travels to shows structure. Each real block is matched to placebo levels
//   displaced 1-3 ATR, touched from the same side, searched from the same bar. A mitigated block that
//   merely matches its placebo is a dead level that price happened to revisit.
//
//   Reference arm: ACTIVE (unmitigated) OB first touches, measured in ORIGINAL polarity, so the
//   dead-level result has something live to be compared against.
//
// 4h. BTC/ETH/SOL/XRP and BNB/ADA/LTC/LINK reported separately. Existing data only, no fetching.

import { loadCandles } from "../../backtest/lib/load-candles.js";
import { computeSMC } from "./calc.js";

const ATR_LEN = 14, W = 12, N_PLACEBO = 3, MAX_WAIT = 500, MIN_N = 60, SEED = 20260821;
const GROUPS = {
  "ORIGINAL BTC/ETH/SOL/XRP": ["BTC", "ETH", "SOL", "XRP"],
  "FRESH BNB/ADA/LTC/LINK": ["BNB", "ADA", "LTC", "LINK"],
};

const mean = (xs) => (xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : NaN);
const sd = (xs) => { const m = mean(xs); return Math.sqrt(mean(xs.map((x) => (x - m) ** 2))); };

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function atrSeries(c, L) {
  const tr = c.map((x, i) => (i === 0 ? x.h - x.l : Math.max(x.h - x.l, Math.abs(x.h - c[i - 1].c), Math.abs(x.l - c[i - 1].c))));
  const o = new Array(c.length).fill(NaN);
  let s = 0; for (let i = 0; i < L; i++) s += tr[i];
  o[L - 1] = s / L;
  for (let i = L; i < c.length; i++) o[i] = (o[i - 1] * (L - 1) + tr[i]) / L;
  return o;
}
// two-proportion z
function propZ(a, b) {
  const na = a.length, nb = b.length;
  if (!na || !nb) return NaN;
  const xa = a.reduce((s, v) => s + v, 0), xb = b.reduce((s, v) => s + v, 0);
  const pa = xa / na, pb = xb / nb, pp = (xa + xb) / (na + nb);
  const se = Math.sqrt(pp * (1 - pp) * (1 / na + 1 / nb));
  return se > 0 ? (pa - pb) / se : NaN;
}
function welch(a, b) {
  const na = a.length, nb = b.length;
  if (na < 2 || nb < 2) return NaN;
  const va = sd(a) ** 2 * na / (na - 1), vb = sd(b) ** 2 * nb / (nb - 1);
  return (mean(a) - mean(b)) / Math.sqrt(va / na + vb / nb);
}

// first bar at/after `from` where price enters [lo,hi] coming from `side` ("above" | "below")
function firstReturn(c, from, lo, hi, side) {
  const end = Math.min(c.length - 1, from + MAX_WAIT);
  for (let j = from; j <= end; j++) {
    if (side === "above" ? c[j].l <= hi : c[j].h >= lo) return j;
  }
  return -1;
}
// reaction over W bars, positive = level acted with the polarity given by `flipUp`
function reaction(c, t, level, flipUp) {
  const k = Math.min(c.length - 1, t + W);
  if (k <= t) return null;
  const ret = (c[k].c - level) / level;
  return { signed: flipUp ? ret : -ret, rejected: flipUp ? (c[t].c > level ? 1 : 0) : (c[t].c < level ? 1 : 0) };
}

async function main() {
  console.log("MITIGATED LEVELS — do they still react, and does polarity FLIP?");
  console.log("Sign convention fixed before running: POSITIVE = flipped polarity (the breaker reading),");
  console.log("NEGATIVE = retained original polarity. Placebos displaced 1-3 ATR, same side, same start.\n");

  for (const [label, insts] of Object.entries(GROUPS)) {
    const acc = {
      mitBear: { real: [], plac: [], rej: [], prej: [] },   // broke up, returns down -> support if flipped
      mitBull: { real: [], plac: [], rej: [], prej: [] },   // broke down, returns up -> resistance if flipped
      activeRef: { real: [], plac: [] },                    // live OBs, ORIGINAL polarity
    };
    for (const inst of insts) {
      const c = await loadCandles("4h", inst);
      if (c.length < 500) continue;
      const atr = atrSeries(c, ATR_LEN);
      const { orderBlocks } = computeSMC(c);
      const rnd = mulberry32(SEED + inst.length);

      for (const ob of orderBlocks) {
        const a0 = atr[ob.createdBarIdx];
        if (!Number.isFinite(a0) || a0 <= 0) continue;
        const lo = ob.barLow, hi = ob.barHigh;

        if (ob.mitigatedBarIdx !== null) {
          // ---- MITIGATED: does the dead level still do anything on the return?
          const from = ob.mitigatedBarIdx + 1;
          const side = ob.side === "bearish" ? "above" : "below";   // where price returns FROM
          const t = firstReturn(c, from, lo, hi, side);
          if (t < 0) continue;
          const level = ob.side === "bearish" ? hi : lo;            // edge met on the way back
          const flipUp = ob.side === "bearish";                     // flipped bearish OB = support = up
          const r = reaction(c, t, level, flipUp);
          if (!r) continue;
          const bucket = ob.side === "bearish" ? acc.mitBear : acc.mitBull;
          bucket.real.push(r.signed); bucket.rej.push(r.rejected);
          for (let m = 0; m < N_PLACEBO; m++) {
            const u = 1 + 2 * rnd(), sgn = rnd() < 0.5 ? -1 : 1;
            const lvl = level + sgn * u * atr[Math.min(from, c.length - 1)];
            if (lvl > lo && lvl < hi) continue;
            const tp = firstReturn(c, from, lvl, lvl, side);
            if (tp < 0) continue;
            const rp = reaction(c, tp, lvl, flipUp);
            if (rp) { bucket.plac.push(rp.signed); bucket.prej.push(rp.rejected); }
          }
        } else {
          // ---- ACTIVE reference: first touch of a live block, ORIGINAL polarity
          const from = ob.createdBarIdx + 1;
          const side = ob.side === "bullish" ? "above" : "below";
          const t = firstReturn(c, from, lo, hi, side);
          if (t < 0) continue;
          const level = ob.side === "bullish" ? hi : lo;
          const flipUp = ob.side === "bullish";                     // live bullish OB holding = up
          const r = reaction(c, t, level, flipUp);
          if (r) acc.activeRef.real.push(r.signed);
        }
      }
    }

    console.log(`===== ${label}`);
    const show = (name, b, withRej) => {
      if (b.real.length < MIN_N) return console.log(`  ${name.padEnd(34)} n=${b.real.length} -- below n>=${MIN_N}`);
      let line = `  ${name.padEnd(34)} n=${String(b.real.length).padStart(5)}  reaction ${(mean(b.real) * 100).toFixed(4)}%`;
      if (b.plac.length) line += `  vs placebo ${(mean(b.plac) * 100).toFixed(4)}%  Welch t=${welch(b.real, b.plac).toFixed(2)}`;
      if (withRej && b.rej.length) line += `  reject ${(mean(b.rej) * 100).toFixed(1)}% vs ${(mean(b.prej) * 100).toFixed(1)}%  z=${propZ(b.rej, b.prej).toFixed(2)}`;
      console.log(line);
    };
    show("MITIGATED bearish OB (return down)", acc.mitBear, true);
    show("MITIGATED bullish OB (return up)", acc.mitBull, true);
    show("ACTIVE OB first touch [reference]", acc.activeRef, false);
    console.log("");
  }
  console.log("POSITIVE reaction on a mitigated block = polarity FLIPPED (breaker behaviour, iapaulo's read).");
  console.log("A mitigated block matching its placebo = a dead level, and htfContext's activeOnly default is right.");
}

main().catch((e) => { console.error("Fatal:", e); process.exit(1); });
